-- 为 sys_ai_provider 表添加 proxy 代理地址字段（幂等） SET @dbname = DATABASE(); SET @tablename = 'sys_ai_provider'; SET @columnname = 'sys_ai_provider_proxy'; SET @preparedStatement = (SELECT IF(   (     SELECT COUNT(*) FROM INFORMATION_SCHEMA.COLUMNS     WHERE TABLE_SCHEMA = @dbname       AND TABLE_NAME = @tablename       AND COLUMN_NAME = @columnname   ) > 0,   'SELECT 1',   CONCAT('ALTER TABLE `', @tablename, '` ADD COLUMN `', @columnname, '` VARCHAR(512) NULL COMMENT ''HTTP代理地址（如 http://127.0.0.1:7890、socks5://127.0.0.1:1080）'' AFTER `sys_ai_provider_extra`') )); PREPARE alterIfNotExists FROM @preparedStatement; EXECUTE alterIfNotExists; DEALLOCATE PREPARE alterIfNotExists;